import json
import os

task_dir = "/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-8/play/users/u019/system/state/workspace/programs/"
json_path = os.path.join(task_dir, "task-1b7868f1.json")

with open(json_path, 'r') as f:
    pairs = json.load(f)

demo6_in = pairs[5]["input"]
demo6_out = pairs[5]["output"]

def find_markers(grid):
    """Find all marker positions and return sorted markers"""
    markers = []
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 1:
                markers.append((r, c))
    # Sort by marker value position, then apply - but what order?
    # Let's keep original order (top-to-bottom, left-to-right)
    return markers

def transform_no_overwrite(grid):
    """Apply footers, but only if cell is currently background (6)"""
    H, W = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    footer_patterns = [
        [0, 5, 7, 8, 8, 8, 8, 8, 8],
        [0, 2, 2, 8, 8, 8, 8, 8, 8],
        [9, 6, 7, 8, 8, 8, 8, 8, 8],
    ]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 1:
                for fi, fr in enumerate(footer_patterns):
                    target_r = r + 1 + fi
                    if target_r < H:
                        for ci in range(3):  # 3 columns
                            target_c = c + ci
                            if target_r < H and target_c < W:
                                # Only write if cell is background (6)
                                if result[target_r][target_c] == 6:
                                    result[target_r][target_c] = fr[ci]
    return result

# Test
result = transform_no_overwrite(demo6_in)
all_match = True
for i, (r1, r2) in enumerate(zip(result, demo6_out)):
    if r1 != r2:
        print(f"Row {i} mismatch:")
        print(f"  Got:        {r1}")
        print(f"  Expected:   {r2}")
        all_match = False

if all_match:
    print("PASSED!")
else:
    print("FAILED")

# Also test with Footers also overwrite other footers
def transform_with_overwrite(grid):
    H, W = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    footer_patterns = [
        [0, 5, 7, 8, 8, 8, 8, 8, 8],
        [0, 2, 2, 8, 8, 8, 8, 8, 8],
        [9, 6, 7, 8, 8, 8, 8, 8, 8],
    ]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 1:
                for fi, fr in enumerate(footer_patterns):
                    target_r = r + 1 + fi
                    if 0 <= target_r < H:
                        for ci in range(3):
                            target_c = c + ci
                            if 0 <= target_c < W:
                                result[target_r][target_c] = fr[ci]

    return result

result2 = transform_with_overwrite(demo6_in)
print("\n\nWith overwrite test:")
matches = sum(1 for r1, r2 in zip(result2, demo6_out) if r1 == r2)
print(f"Matched {matches} of {len(demo6_out)} rows")
